    static let appGroupIdentifier = "group.com.beadinventory.shared"

    /// 共享图片的文件名
    private let sharedImageFileName = "shared_image.jpg"

    /// 标记文件名（表示有新图片待处理）
    private let pendingFlagFileName = "pending_image"

    /// 当前待处理的共享图片
